    // Vector 19: seventeen bytes 0xFF 0xEE 0xDD 0xCC 0xBB 0xAA 0x99 0x88 0x77 0x66 0x55 0x44 0x33 0x22 0x11 0x00 0x01
    sr1_lengths[19] = 17;
